export const getPutScenarioSyncUrl = () => {




  return `/api/scenarios/sync`
}

/**
 * Bearer session required. Same last-write-wins rules as account sync. Mobile sends `updatedAt`. Web omits it and the server assigns the time. apiKey and apiSecret fields anywhere in `scenarios` are removed before the blob is stored. Other fields are kept.
 * @summary Write the signed-in user's strategy scenario list
 */
export const putScenarioSync = async (scenarioSyncWrite: ScenarioSyncWrite, options?: Parameters<typeof customFetch>[1]): Promise<SyncAccepted> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<SyncAccepted>(getPutScenarioSyncUrl(),
  {
    ...options,
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(scenarioSyncWrite)
  }
);}





